using System.Text.Json;
using Avalonia;
using Avalonia.Automation;
using Avalonia.Controls;
using Avalonia.Controls.ApplicationLifetimes;
using Avalonia.Headless;
using Avalonia.Input;
using Avalonia.Input.Raw;
using Avalonia.Media;
using Avalonia.Media.Imaging;
using Avalonia.Threading;
using Avalonia.VisualTree;
using Verifier.Desktop;
internal sealed class TrialPageProbeApplication:Application
{
    private sealed record Case(string Id,double Width,double ViewportWidth,bool English,string Host,string Database,string ValidInput,string InvalidInput,bool Consent,bool Ready,string Error);
    public override void Initialize(){Styles.Add(new Avalonia.Themes.Fluent.FluentTheme());}
    public override void OnFrameworkInitializationCompleted()
    {
        var life=(IClassicDesktopStyleApplicationLifetime)ApplicationLifetime!;var args=life.Args!;var cases=JsonSerializer.Deserialize<Case[]>(File.ReadAllText(args[1]),new JsonSerializerOptions{PropertyNameCaseInsensitive=true})!;var output=args[2];Directory.CreateDirectory(output);
        var page=new WebTrialPage{ReducedMotion=!(args.Length>3&&args[3]=="hover-normal"),Width=cases[0].Width};var canvas=new Canvas{Width=1220,Height=1600,Background=Brush.Parse("#313338"),UseLayoutRounding=false};canvas.Children.Add(page);Canvas.SetLeft(page,30);Canvas.SetTop(page,60);var w=new Window{Title="Replica TrialPage verification",Width=1260,Height=1200,Content=canvas,UseLayoutRounding=false};life.MainWindow=w;
        object Box(Control c){var p=c.TranslatePoint(default,page)??default;return new{x=p.X,y=p.Y,width=c.Bounds.Width,height=c.Bounds.Height};}
        string Color(IBrush b){var c=((ISolidColorBrush)b).Color;return c.A==0?"rgba(0, 0, 0, 0)":$"rgb({c.R}, {c.G}, {c.B})";}
        object Item(Control c,string? text=null){var t=c is WebSystemTextBlock block?block:c.GetVisualDescendants().OfType<WebSystemTextBlock>().FirstOrDefault();return new{box=Box(c),text=text??t?.Text??"",fontSize=(t?.FontSize??14)+"px",lineHeight=(t?.LineHeight??22.4)+"px",color=t is null?"rgb(219, 222, 225)":Color(t.Foreground!)};}
        object Notice(Control n){var text=n.GetVisualDescendants().OfType<WebSystemTextBlock>().Take(2).ToArray();return new{root=Item(n),role=n is WebNotice web?(web.Kind=="error"?"alert":"note"):null,icon=n.GetVisualDescendants().OfType<SvgIcon>().FirstOrDefault() is{} icon?Item(icon):null,title=Item(text[0]),body=Item(text[1])};}
        object Read(string id){var guideItems=((Panel)page.Guidance).Children.Cast<Panel>().Select(item=>Item(item.Children[0])).ToArray();var shell=page.PlanTable.GetVisualDescendants().OfType<WebSurfaceBox>().First();var table=(Panel)shell.Child!;var cells=table.GetVisualDescendants().OfType<Control>().Where(c=>c.GetType().Name=="Cell").ToArray();return new{id,root=Box(page),heading=Item(page.Heading),title=Item(page.Heading.TitleText),description=Item(page.Heading.DescriptionText),split=Item(page.ConnectionSplit),panels=page.Panels.Take(2).Select(p=>Item(p)).ToArray(),subheadings=page.Subheadings.Select(h=>Item(h)).ToArray(),fields=page.Fields.Select((f,i)=>new{root=Item(f),label=Item(f.LabelText),input=new{box=Box(page.Inputs[i]),value=page.Inputs[i].Text,id=AutomationProperties.GetAutomationId(page.Inputs[i]),type="text"}}).ToArray(),notices=new[]{page.IsolationNotice,page.ErrorNotice,page.ReadyNotice}.Where(x=>x is not null).Select(x=>Notice(x!)).ToArray(),guide=new{list=Item(page.Guidance),items=guideItems,note=Item(page.GuidanceNote)},section=Item(page.PlanSection),table=new{shell=Item(page.PlanTable),table=Item(table),headers=cells.Take(3).Select(c=>Item(c)).ToArray(),rows=Enumerable.Range(1,3).Select(r=>new{cells=cells.Skip(r*3).Take(3).Select(c=>Item(c)).ToArray()}).ToArray()},values=new{panel=Item(page.Panels[2]),note=Item(page.ValueNote),split=Item(page.ValueSplit)},consent=new{root=Item(page.ConsentChoice),input=new{box=Box(page.ConsentChoice.Checkbox),@checked=page.ConsentChoice.IsSelected},label=Item(page.ConsentChoice.Label)}};}
        Case current=cases[0];void Present(Case c){current=c;page.Width=c.Width;page.SetPresentation(new(c.English,c.Host,c.Database,c.ValidInput,c.InvalidInput,c.Consent,c.Ready,c.Error),c.ViewportWidth);w.UpdateLayout();}
        void Capture(string name){using var bitmap=new RenderTargetBitmap(new PixelSize(2440,3200),new Vector(192,192));bitmap.Render(canvas);bitmap.Save(Path.Combine(output,name),new PngBitmapEncoderOptions());}
        var changes=new List<object>();page.Changed+=(_,v)=>changes.Add(new{view=v,focused=w.FocusManager?.GetFocusedElement() is Control f?AutomationProperties.GetAutomationId(f):""});
        if(args[0]=="--trialpage-window")
        {
            w.Content=null;var scroll=new ScrollViewer{Content=canvas,HorizontalScrollBarVisibility=Avalonia.Controls.Primitives.ScrollBarVisibility.Disabled,VerticalScrollBarVisibility=Avalonia.Controls.Primitives.ScrollBarVisibility.Auto};var frame=new Grid();frame.Children.Add(scroll);w.Content=frame;w.Height=900;
            var scrollUtility=new Button{Content="Trial scroll",Width=110,Height=24,HorizontalAlignment=Avalonia.Layout.HorizontalAlignment.Right,VerticalAlignment=Avalonia.Layout.VerticalAlignment.Top};AutomationProperties.SetAutomationId(scrollUtility,"TrialPage-scroll");frame.Children.Add(scrollUtility);scrollUtility.Click+=(_,_)=>scroll.Offset=new Vector(0,scroll.Offset.Y<100?650:0);
            var setup=new Button{Content="Trial setup next",Width=140,Height=24};AutomationProperties.SetAutomationId(setup,"TrialPage-setup");canvas.Children.Add(setup);var index=1;setup.Click+=(_,_)=>Present(cases[index++%cases.Length]);
            var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(60)};timer.Tick+=(_,_)=>{w.UpdateLayout();File.WriteAllText(Path.Combine(output,"trialpage-input.json"),JsonSerializer.Serialize(new{changes,view=page.View,focused=w.FocusManager?.GetFocusedElement() is Control f?AutomationProperties.GetAutomationId(f):"",row=Read(current.Id),tableRows=page.PlanTable.GetVisualDescendants().OfType<Panel>().Where(x=>x.GetType().Name=="TableRow").Skip(1).Select(x=>new{box=Box(x),background=Color(x.Background!),hover=x.IsPointerOver})}));};w.Opened+=(_,_)=>{Present(cases[0]);timer.Start();};w.Closed+=(_,_)=>timer.Stop();base.OnFrameworkInitializationCompleted();return;
        }
        w.Opened+=(_,_)=>Dispatcher.UIThread.Post(async()=>{
            if(args.Length>3&&args[3]=="baseline"){var baselineRows=new List<object>();foreach(var c in cases){Present(c);await Dispatcher.UIThread.InvokeAsync(()=>{},DispatcherPriority.Background);w.UpdateLayout();baselineRows.Add(new{id=c.Id,notices=new[]{page.IsolationNotice,page.ErrorNotice,page.ReadyNotice}.Where(n=>n is not null).Select(n=>{var title=n!.GetVisualDescendants().OfType<WebSystemTextBlock>().First();var p=title.TranslatePoint(default,page)??default;return new{title=title.Text,baseline=p.Y+title.SystemBaseline,titleWidths=title.SystemLineWidths};}).ToArray()});}File.WriteAllText(Path.Combine(output,"trialpage-baseline-native.json"),JsonSerializer.Serialize(new{dpr=w.RenderScaling,rows=baselineRows},new JsonSerializerOptions{WriteIndented=true}));w.Close();Console.WriteLine("Recorded "+baselineRows.Count+" TrialPage baseline-only cases");return;}
            if(args.Length>3&&args[3]=="hover"){
                var hoverRows=new List<object>();foreach(var c in cases)foreach(var reduced in new[]{false,true}){page.ReducedMotion=reduced;Present(c);await Dispatcher.UIThread.InvokeAsync(()=>{},DispatcherPriority.Background);w.UpdateLayout();var row=page.PlanTable.GetVisualDescendants().OfType<Panel>().First(x=>x.GetType().Name=="TableRow"&&x.GetVisualDescendants().OfType<WebSystemTextBlock>().Any(t=>t.Text=="1"));var point=row.TranslatePoint(new Point(row.Bounds.Width/2,row.Bounds.Height/2),w)!.Value;int callbackCount=0;EventHandler<WebTrialView> changed=(_,_)=>callbackCount++;page.Changed+=changed;
                    foreach(var mode in new[]{"hover","leave","cancel"}){if(mode=="leave")w.MouseMove(new Point(10,10));else{w.MouseMove(point);if(mode=="cancel"){await Task.Delay(60);w.CaptureRenderedFrame();w.MouseMove(new Point(10,10));}}await Task.Delay(200);w.CaptureRenderedFrame();hoverRows.Add(new{id=c.Id,reduced,mode,background=Color(row.Background!),hover=row.IsPointerOver,callbacks=callbackCount});if(mode=="hover"&&!reduced)Capture("trialpage-hover-"+c.Id+".png");}
                    page.Changed-=changed;canvas.Children.Remove(page);var detached=Color(row.Background!);canvas.Children.Add(page);hoverRows.Add(new{id=c.Id,reduced,mode="detach",background=detached,hover=false,callbacks=callbackCount});}
                File.WriteAllText(Path.Combine(output,"trialpage-hover-native.json"),JsonSerializer.Serialize(hoverRows,new JsonSerializerOptions{WriteIndented=true}));w.Close();return;
            }
            if(args.Length>3&&args[3]=="table"){
                var tableRows=new List<object>();foreach(var c in cases){Present(c);await Dispatcher.UIThread.InvokeAsync(()=>{},DispatcherPriority.Background);w.UpdateLayout();tableRows.Add(Read(c.Id));Capture("trialpage-table-"+c.Id+".png");}
                var motion=new List<object>();foreach(var reduced in new[]{false,true}){page.ReducedMotion=reduced;Present(cases[0]);await Dispatcher.UIThread.InvokeAsync(()=>{},DispatcherPriority.Background);var isolation=page.IsolationNotice;var field=isolation.GetType().GetField("_motion",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)!;bool mounted=field.GetValue(isolation) is not null;await Task.Delay(300);var settled=isolation.Opacity;canvas.Children.Remove(page);bool disposed=field.GetValue(isolation) is null;canvas.Children.Add(page);bool reattached=field.GetValue(isolation) is not null;await Task.Delay(300);motion.Add(new{reduced,mounted,disposed,reattached,settled,reattachOpacity=isolation.Opacity});}
                File.WriteAllText(Path.Combine(output,"trialpage-table-native.json"),JsonSerializer.Serialize(new{dpr=w.RenderScaling,rows=tableRows,motion},new JsonSerializerOptions{WriteIndented=true}));w.Close();return;
            }
            var rows=new List<object>();foreach(var c in cases){Present(c);await Dispatcher.UIThread.InvokeAsync(()=>{},DispatcherPriority.Background);w.UpdateLayout();rows.Add(Read(c.Id));if(c.Id is "ko-1280-default" or "en-960-both")Capture("trialpage-"+c.Id+".png");}
            var lifecycle=new List<object>();foreach(var c in cases.Where(c=>c.Id is "ko-1280-default" or "en-960-both" or "ko-1280-ready")){canvas.Children.Remove(page);await Dispatcher.UIThread.InvokeAsync(()=>{},DispatcherPriority.Background);Present(c);canvas.Children.Add(page);await Dispatcher.UIThread.InvokeAsync(()=>{},DispatcherPriority.Background);w.UpdateLayout();lifecycle.Add(new{attached=canvas.Children.Contains(page),row=Read(c.Id)});}
            var inputs=new List<object>();if(ReplicaPlatform.IsHeadless){foreach(var en in new[]{false,true}){Present(cases.Single(c=>c.English==en&&c.ViewportWidth==1280&&c.Ready&&c.Error.Length>0));for(var i=0;i<4;i++){var editor=page.Inputs[i];editor.Focus(NavigationMethod.Tab);w.KeyPress(Key.A,(OperatingSystem.IsMacOS()?RawInputModifiers.Meta:RawInputModifiers.Control),PhysicalKey.None,"a");w.KeyRelease(Key.A,(OperatingSystem.IsMacOS()?RawInputModifiers.Meta:RawInputModifiers.Control),PhysicalKey.None,"a");w.KeyTextInput("owned-example");await Dispatcher.UIThread.InvokeAsync(()=>{},DispatcherPriority.Background);inputs.Add(new{language=en?"en":"ko",phase="field"+i,view=page.View,sameEditor=ReferenceEquals(editor,page.Inputs[i]),focused=w.FocusManager?.GetFocusedElement() is Control fieldFocus?AutomationProperties.GetAutomationId(fieldFocus):"",okVisible=page.ReadyNotice is not null,errorVisible=page.ErrorNotice is not null});}var choice=page.ConsentChoice;choice.Checkbox.Focus(NavigationMethod.Tab);w.KeyPress(Key.Space,RawInputModifiers.None,PhysicalKey.Space," ");w.KeyRelease(Key.Space,RawInputModifiers.None,PhysicalKey.Space," ");await Dispatcher.UIThread.InvokeAsync(()=>{},DispatcherPriority.Loaded);inputs.Add(new{language=en?"en":"ko",phase="consent",view=page.View,replaced=!ReferenceEquals(choice,page.ConsentChoice),focused=w.FocusManager?.GetFocusedElement() is Control consentFocus?AutomationProperties.GetAutomationId(consentFocus):""});}}
            File.WriteAllText(Path.Combine(output,"trialpage-native.json"),JsonSerializer.Serialize(new{dpr=w.RenderScaling,rows,lifecycle,inputs},new JsonSerializerOptions{WriteIndented=true}));w.Close();Console.WriteLine("Recorded "+rows.Count+" TrialPage cases");
        },DispatcherPriority.Background);base.OnFrameworkInitializationCompleted();
    }
}
